[
  {
    "statement": "When restoring peatlands afforested for commercial forestry, cutting trees and rewetting peat shows more comprehensive restoration outcomes compared to only cutting trees.",
    "citations": [
      "1732",
      "1731"
    ]
  },
  {
    "statement": "The combined approach of cutting trees and rewetting peat increases the abundance of wetland-characteristic plants.",
    "citations": [
      "1732"
    ]
  },
  {
    "statement": "Tree removal alone only increases the cover of some herb species like cottongrasses and sedges.",
    "citations": [
      "1731"
    ]
  },
  {
    "statement": "The combined intervention of cutting trees and rewetting peat increases Sphagnum moss cover.",
    "citations": [
      "1732"
    ]
  },
  {
    "statement": "Tree removal alone decreases Sphagnum moss cover over three years.",
    "citations": [
      "1731"
    ]
  },
  {
    "statement": "Both cutting trees alone and combining tree cutting with rewetting peat increase plant species richness.",
    "citations": []
  },
  {
    "statement": "One study found the increase in plant species richness is smaller when trees are removed from rewetted plots compared to when trees are removed from drained plots.",
    "citations": [
      "1731"
    ]
  },
  {
    "statement": "Water table management is crucial for peatland restoration.",
    "citations": [
      "1756"
    ]
  },
  {
    "statement": "Rewetting peatlands alone can result in increased Sphagnum moss cover.",
    "citations": [
      "1756"
    ]
  },
  {
    "statement": "Rewetting peatlands alone can result in reduced tree and shrub cover.",
    "citations": [
      "1756"
    ]
  },
  {
    "statement": "Rewetting peatlands alone can result in increased herb cover, including sedges and cottongrasses.",
    "citations": [
      "1756"
    ]
  }
]

[
  {
    "statement": "The evidence for habitat corridor effectiveness in conserving peatland vegetation is extremely limited.",
    "citations": []
  },
  {
    "statement": "Only one study was found that directly examined peatland vegetation in habitat corridors.",
    "citations": [
      "1730"
    ]
  },
  {
    "statement": "The single study on peatland vegetation in habitat corridors was conducted in a tropical peat swamp forest corridor in Indonesia.",
    "citations": [
      "1730"
    ]
  },
  {
    "statement": "A single study found that a peat swamp forest corridor contained 5,819 trees per hectare.",
    "citations": [
      "1730"
    ]
  },
  {
    "statement": "The peat swamp forest corridor included 331 large trees per hectare.",
    "citations": [
      "1730"
    ]
  },
  {
    "statement": "The peat swamp forest corridor included 1,360 saplings per hectare.",
    "citations": [
      "1730"
    ]
  },
  {
    "statement": "The peat swamp forest corridor included 4,128 seedlings per hectare.",
    "citations": [
      "1730"
    ]
  },
  {
    "statement": "A study recorded 18-29 tree species in a peat swamp forest corridor.",
    "citations": [
      "1730"
    ]
  },
  {
    "statement": "The number of tree species found in the peat swamp forest corridor varied by size class.",
    "citations": [
      "1730"
    ]
  },
  {
    "statement": "No studies were found that evaluated habitat corridors for peatland vegetation in areas of energy production or mining.",
    "citations": [
      "1739"
    ]
  },
  {
    "statement": "No studies were found that evaluated habitat corridors for peatland vegetation across service corridors.",
    "citations": [
      "1742"
    ]
  },
