    ]
  },
  {
    "statement": "Wearing snowshoes to prevent trampling is a main management approach.",
    "citations": [
      "1754"
    ]
  },
  {
    "statement": "Restricting vehicle use on peatlands is a main management approach.",
    "citations": [
      "1749"
    ]
  },
  {
