[
  {
    "statement": "Following the rewetting of drained peatlands, plant community composition changes, with drier grassland communities being replaced by communities characteristic of wetlands or peatlands.",
    "citations": [
      "1756"
    ]
  },
  {
    "statement": "Sphagnum moss cover typically increases following the rewetting of drained peatlands.",
    "citations": [
      "1756",
      "1732"
    ]
  },
  {
    "statement": "The response of Sphagnum moss to rewetting can be species-specific.",
    "citations": [
      "1756",
      "1732"
    ]
  },
  {
    "statement": "Herb cover in drained peatlands generally increases after rewetting.",
    "citations": [
      "1756",
      "1732"
    ]
  },
  {
    "statement": "The cover of sedges tends to increase after the rewetting of drained peatlands.",
    "citations": [
      "1756",
      "1732"
    ]
  },
  {
    "statement": "The cover of cottongrass tends to increase after the rewetting of drained peatlands.",
    "citations": [
      "1756",
      "1732"
    ]
  },
  {
    "statement": "The cover of reeds and rushes tends to increase after the rewetting of drained peatlands.",
