[
  {
    "statement": "The evidence for actions to mitigate impacts of service corridors on peatland vegetation is very limited.",
    "citations": []
  },
  {
    "statement": "Only one study was found that directly evaluated mitigation effects on peatland vegetation.",
    "citations": [
      "1741"
    ]
  },
  {
    "statement": "A before-and-after study in a fen in the USA found that restoring water flow across a road, along with general rewetting, increased the cover of wet peatland sedges.",
    "citations": [
      "1741"
    ]
  },
  {
    "statement": "Restoring water flow across a road, along with general rewetting, decreased the cover of grasses preferring drier conditions.",
    "citations": [
      "1741"
    ]
  },
  {
    "statement": "No studies were found that evaluated the effects of retaining or creating habitat corridors across service corridors.",
